    `START_TIME_` datetime(3) NOT NULL,
    `END_TIME_` datetime(3) DEFAULT NULL,
    `DURATION_` bigint(20) DEFAULT NULL,
    `TRANSACTION_ORDER_` int(11) DEFAULT NULL,
    `DELETE_REASON_` varchar(4000) COLLATE utf8_bin DEFAULT NULL,
