-- ----------------------------
-- Table structure for add_sign_record
-- ----------------------------
DROP TABLE IF EXISTS `add_sign_record`;
CREATE TABLE `add_sign_record` (
    `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
    `type` tinyint(4) NOT NULL COMMENT '加签类型：1前加签，2后加签',
    `task_id` varchar(64) NOT NULL COMMENT '任务id',
    `p_task_id` varchar(64) NOT NULL COMMENT '父任务id',
    `pass_flag` tinyint(4) DEFAULT '0' COMMENT '审批通过标志，如果前加签的某个父任务的子任务都通过了，要还原父任务',
    `is_delete` tinyint(4) unsigned NOT NULL DEFAULT '0' COMMENT '是否删除',
    `gmt_create` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    `gmt_modify` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
    PRIMARY KEY (`id`),
    KEY `idx_task_id` (`task_id`),
    KEY `idx_p_task_id` (`p_task_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='加签记录表';

-- ----------------------------
-- Records of add_sign_record
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for business_status
-- ----------------------------
DROP TABLE IF EXISTS `business_status`;
CREATE TABLE `business_status` (
    `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
    `source_id` varchar(64) NOT NULL COMMENT '来源表id',
    `source_type` int(11) NOT NULL COMMENT '业务数据类型',
    `source_status` int(11) NOT NULL COMMENT '业务数据枚举',
    `biz_type` varchar(32) DEFAULT NULL COMMENT '业务含义',
    `is_delete` tinyint(4) unsigned NOT NULL DEFAULT '0' COMMENT '是否删除',
    `gmt_create` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    `gmt_modify` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
    PRIMARY KEY (`id`),
    UNIQUE KEY `uniq_source_id_type` (`source_id`,`source_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='业务状态表';

-- ----------------------------
-- Records of business_status
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for model_ext
-- ----------------------------
DROP TABLE IF EXISTS `model_ext`;
CREATE TABLE `model_ext` (
    `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
    `model_id` varchar(64) NOT NULL COMMENT 'act_re_model表id',
    `ext_json` longtext COMMENT '模型额外信息json',
    `note` varchar(128) NOT NULL DEFAULT '' COMMENT '模型描述',
    `is_delete` tinyint(4) unsigned NOT NULL DEFAULT '0' COMMENT '是否删除',
    `gmt_create` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    `gmt_modify` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
    PRIMARY KEY (`id`),
    UNIQUE KEY `uniq_model_id` (`model_id`)
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COMMENT='模型扩展数据表';

