-- ----------------------------
-- Table structure for node_back_record
-- ----------------------------
DROP TABLE IF EXISTS `node_back_record`;
CREATE TABLE `node_back_record` (
    `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
    `process_instance_id` varchar(64) NOT NULL COMMENT '流程实例id',
    `source_task_activity_id` varchar(64) NOT NULL COMMENT '操作时原节点任务节点id',
    `sink_task_activity_id` varchar(64) NOT NULL COMMENT '回退到的节点id',
    `process_start_user_id` varchar(64) NOT NULL COMMENT '流程发起人id，索引协助减小查询范围',
    `type` tinyint(4) NOT NULL COMMENT '回退类型，1撤回，2驳回',
    `handler_id` varchar(64) NOT NULL COMMENT '操作人id',
    `status` tinyint(4) NOT NULL DEFAULT '1' COMMENT '是否还未处理此次回退，1未处理，0已处理',
    `jump_to_source_flag` tinyint(4) NOT NULL DEFAULT '0' COMMENT 'sink节点正常处理后是否需要跳回source节点',
    `gmt_create` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    `gmt_modify` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
    PRIMARY KEY (`id`),
    KEY `idx_pi_sink_ta_id` (`process_instance_id`,`sink_task_activity_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='节点回退记录表';

-- ----------------------------
-- Records of node_back_record
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for notify_record
-- ----------------------------
DROP TABLE IF EXISTS `notify_record`;
CREATE TABLE `notify_record` (
    `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
    `type` int(11) NOT NULL COMMENT '通知类型；1通知；2抄送；3催办',
    `process_instance_id` varchar(64) NOT NULL COMMENT '流程实例id',
    `task_id` varchar(64) NOT NULL DEFAULT '' COMMENT '任务id，可以为空，比如流程启动时抄送',
    `sender_id` varchar(64) NOT NULL COMMENT '发送人id',
    `receiver_id` varchar(64) NOT NULL COMMENT '接收者id',
    `message` varchar(255) NOT NULL COMMENT '通知信息',
    `read_flag` tinyint(4) NOT NULL DEFAULT '0' COMMENT '已读标识',
    `is_delete` tinyint(4) unsigned NOT NULL DEFAULT '0' COMMENT '是否删除',
    `gmt_create` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    `gmt_modify` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
    PRIMARY KEY (`id`),
    KEY `idx_sender_id` (`sender_id`),
    KEY `idx_receiver_id` (`receiver_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='通知记录表';

-- ----------------------------
-- Records of notify_record
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for operate_record
-- ----------------------------
DROP TABLE IF EXISTS `operate_record`;
CREATE TABLE `operate_record` (
    `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
    `type` varchar(32) NOT NULL COMMENT '操作类型',
    `biz_type` varchar(32) DEFAULT NULL COMMENT '操作-业务自扩展类型',
    `process_instance_id` varchar(64) NOT NULL COMMENT '流程实例id',
    `process_definition_id` varchar(64) NOT NULL COMMENT '流程定义id',
    `task_id` varchar(64) DEFAULT NULL COMMENT '任务id，可以为空，比如操作流程撤回',
    `task_activity_id` varchar(64) DEFAULT NULL COMMENT '任务节点id，可以为空',
    `note` varchar(1024) DEFAULT NULL COMMENT '操作备注',
    `handler_id` varchar(64) DEFAULT NULL COMMENT '操作人',
    `gmt_create` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    `gmt_modify` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
    PRIMARY KEY (`id`),
    KEY `idx_process_instance_id` (`process_instance_id`),
    KEY `idx_handler_id` (`handler_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='操作记录表';

-- ----------------------------
-- Records of operate_record
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for process_auth
-- ----------------------------
DROP TABLE IF EXISTS `process_auth`;
CREATE TABLE `process_auth` (
    `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
    `process_instance_id` varchar(64) NOT NULL COMMENT '流程实例id',
    `task_activity_id` varchar(64) DEFAULT NULL COMMENT '任务节点id',
    `source_type` int(11) NOT NULL COMMENT '权限来源，1发起流程，2流程审批，3抄送',
    `user_id` varchar(64) NOT NULL COMMENT '被授权人id',
    `status` tinyint(4) NOT NULL DEFAULT '1' COMMENT '是否有效，1有效，0无效',
    `gmt_create` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    `gmt_modify` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
    PRIMARY KEY (`id`),
    UNIQUE KEY `uniq_u_pi_ta_id` (`user_id`,`process_instance_id`,`task_activity_id`),
    KEY `idx_process_instance_id` (`process_instance_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='流程权限表';

-- ----------------------------
-- Records of process_auth
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for process_instance_ext
-- ----------------------------
DROP TABLE IF EXISTS `process_instance_ext`;
CREATE TABLE `process_instance_ext` (
    `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
    `process_instance_id` varchar(64) NOT NULL COMMENT '流程实例id',
    `sub_module` varchar(32) DEFAULT NULL COMMENT '二级模块枚举',
    `start_user_dept_id` varchar(64) DEFAULT NULL COMMENT '被抄送人id',
    `last_operator_id` varchar(64) DEFAULT NULL COMMENT '最后操作人id',
    `last_operation_type` varchar(32) DEFAULT NULL COMMENT '最后操作类型',
    `gmt_create` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    `gmt_modify` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
    PRIMARY KEY (`id`),
    KEY `idx_process_instance_id` (`process_instance_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='流程实例额外信息表';

-- ----------------------------
-- Records of process_instance_ext
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for task_delegate_rule
-- ----------------------------
DROP TABLE IF EXISTS `task_delegate_rule`;
CREATE TABLE `task_delegate_rule` (
    `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
    `employer_id` varchar(64) NOT NULL COMMENT '转交人id',
    `employee_id` varchar(64) NOT NULL COMMENT '被转交人id',
    `start_time` datetime NOT NULL COMMENT '规则生效时间',
    `end_time` datetime NOT NULL COMMENT '规则结束时间',
    `is_delete` tinyint(4) unsigned NOT NULL DEFAULT '0' COMMENT '是否删除',
    `gmt_create` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    `gmt_modify` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
    PRIMARY KEY (`id`),
    KEY `idx_employer_id` (`employer_id`),
    KEY `idx_employee_id` (`employee_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='任务转交规则表';

-- ----------------------------
-- Records of task_delegate_rule
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for vote_record
-- ----------------------------
DROP TABLE IF EXISTS `vote_record`;
CREATE TABLE `vote_record` (
    `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
    `process_instance_id` varchar(64) NOT NULL COMMENT '流程实例id',
    `voter_id` varchar(64) NOT NULL COMMENT '投票人id',
    `task_activity_id` varchar(64) NOT NULL COMMENT '投票节点id',
    `task_id` varchar(64) NOT NULL COMMENT '任务id',
    `vote_key` varchar(64) NOT NULL COMMENT '标记多次投票属于一次投票',
    `type` varchar(32) NOT NULL COMMENT '投票结果枚举',
    `note` varchar(1024) DEFAULT NULL COMMENT '操作备注',
    `gmt_create` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    `gmt_modify` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
    PRIMARY KEY (`id`),
    KEY `idx_process_instance_id` (`process_instance_id`),
    KEY `idx_voter_id` (`voter_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='投票记录表（任务通过）';

-- ----------------------------
-- Records of vote_record
-- ----------------------------
BEGIN;
COMMIT;

SET FOREIGN_KEY_CHECKS = 1;
